//! Independent current-master declaration-policy comparison.
use crate::lint::Registry;
#[path="../fixtures/original_policies/init_workspace_0660476914.rs"]mod original;
#[path="../fixtures/native-init-workspace/fixture.rs"]mod fixture;
#[path="../../dmb/shared/test_scratch.rs"]mod scratch;
fn record(outcome:&crate::run::Outcome)->serde_json::Value{serde_json::json!({"sites":outcome.run.sites,"notes":outcome.run.notes,"allow_used":outcome.allow_used,"failed":outcome.failed,"text":outcome.text})}
#[test]fn shared_init_policy_preserves_entire_original_headers_roots_table_walk_order_allow_and_reports(){
 for case in fixture::CASES{let root=scratch::dir(&format!("init-workspace-core-{case}"));for(relative,bytes)in fixture::files(case){let target=root.join(relative);std::fs::create_dir_all(target.parent().unwrap()).unwrap();std::fs::write(target,bytes).unwrap();}let options=crate::run::Options{root:root.clone(),lints:vec!["init".into()],no_cache:true,raw:true,..Default::default()};let mut old_registry=Registry::default();original::register(&mut old_registry);let old=crate::run::Engine::new(old_registry,options.clone()).unwrap();let mut current_registry=Registry::default();crate::lints::init::register(&mut current_registry);let current=crate::run::Engine::new(current_registry,options).unwrap();let sem=crate::sem::sem_for(&old.tree).unwrap();assert!(sem.errors.is_empty(),"actual original parsing must succeed: {:?}",sem.errors);let before=old.run_one(old.reg.lints[0].as_ref());let original_scope=old.scopes.for_lint("init","");assert_eq!(original_scope.exempt("code/probe.dm"),*case=="exempt","the ORIGINAL config loader must observe the intended exemption");if *case=="roots"{assert_eq!(original_scope.list("init_roots"),&["/obj/init_workspace = real fixture root owns the initialization chain".to_owned()]);assert!(!before.run.sites.iter().any(|site|matches!(site.rule.as_str(),"world_reads"|"init_lines")),"actual immutable original skips the configured root's per-file checks");}else{assert!(original_scope.list("init_roots").is_empty());}if *case=="exempt"{assert!(!before.run.sites.is_empty(),"original unfiltered table pass still sees exempt sources");assert!(before.run.sites.iter().all(|site|site.rule=="table_init_overrides"));}let after=current.run_one(current.reg.lints[0].as_ref());assert_eq!(record(&after),record(&before),"complete original report/ALLOW/status for {case}");println!("SHARED_INIT_WORKSPACE_OLD={}",serde_json::json!({"case":case,"record":record(&before),"source_text":before.run.sites.iter().map(|site|crate::util::normalize_ws(old.tree.get(&site.rel).unwrap().raw().line(site.line as usize))).collect::<Vec<_>>()}));}
}
